import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";import"./chunks/assets.B-QExMyb.js";var i=JSON.parse(`{"title":"[Chapter 2] Raw Materials Preparation","description":"","frontmatter":{},"headers":[],"relativePath":"en/document/level-0/ch02-preparation.md","filePath":"en/document/level-0/ch02-preparation.md","lastUpdated":1777787579000}`),a={name:`en/document/level-0/ch02-preparation.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="chapter-2-raw-materials-preparation" tabindex="-1">[Chapter 2] Raw Materials Preparation <a class="header-anchor" href="#chapter-2-raw-materials-preparation" aria-label="Permalink to “[Chapter 2] Raw Materials Preparation”">​</a></h1><p>This chapter is somewhat special because it involves monetary transactions. Based on the neutral stance of this project, no specific recommendations will be made. What I can do is tell you what you need to prepare.</p><h2 id="_2-1-obtain-a-vps" tabindex="-1">2.1 Obtain a VPS <a class="header-anchor" href="#_2-1-obtain-a-vps" aria-label="Permalink to “2.1 Obtain a VPS”">​</a></h2><p>You need to obtain a healthy VPS whose IP is not blocked, and complete the following basic preparations in the management panel:</p><ol><li>Install the <strong>Debian</strong> system in the VPS management panel.</li><li>Make a note of the VPS IP address (this article will use <code>&quot;100.200.300.400&quot;</code> to represent it).<div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>This is a deliberately written illegal IP; please replace it with your real IP.</p></div></li><li>Make a note of the VPS SSH remote login port.</li><li>Make a note of the SSH remote login username and password.</li></ol><p>Purchasing a VPS is a relatively complex matter. It is recommended to learn some relevant knowledge first and choose one that fits your financial ability and line quality needs. Additionally, you can choose to take advantage of free offers from major international tech giants (such as the permanent free or limited-time free tiers provided by Oracle and Google). In short, please act according to your means.</p><div class="tip custom-block"><p class="custom-block-title">Note</p><p>Regarding the choice of Debian as the operating system, let me add a few words here: No matter what you hear online, no matter which &quot;guru&quot; tells you that XXX version of Linux is better or XXX version of Linux is cooler, these Linux distro wars <strong>have absolutely nothing to do with you right now</strong>! Using the latest Debian stable release is sufficient to allow your VPS server to run securely and stably while receiving enough optimization (such as cloud-specific kernels, timely BBR support, etc.). Once you are familiar with Linux, it won&#39;t be too late to look back and try other Linux distributions.</p></div><h2 id="_2-2-obtain-a-desired-domain-name" tabindex="-1">2.2 Obtain a Desired Domain Name <a class="header-anchor" href="#_2-2-obtain-a-desired-domain-name" aria-label="Permalink to “2.2 Obtain a Desired Domain Name”">​</a></h2><p>You need to obtain a domain name and add an A record in the DNS settings pointing to your VPS IP address.</p><ol><li>Please choose a reliable international domain registrar. Choose some common domain suffixes, but be careful <strong>not</strong> to use the <code>.cn</code> suffix.</li><li>In the DNS settings, add an <strong>A record</strong> pointing to your VPS IP address (The name of the A record can be anything; this article will use <code>&quot;a-name&quot;</code> to represent it. The full domain name will be represented as <code>&quot;subdomain.yourdomain.com&quot;</code> or <code>&quot;a-name.yourdomain.com&quot;</code>). The effect is shown in the figure below:</li></ol><p><img src="/assets/ch02-img01-a-name.DXHjY1Jd.png" alt="Add A Record" width="2084" height="440"></p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>This is <strong>not</strong> a real, usable URL; please replace it with your real URL.</p></div><h2 id="_2-3-software-to-install-on-your-local-computer" tabindex="-1">2.3 Software to Install on Your Local Computer <a class="header-anchor" href="#_2-3-software-to-install-on-your-local-computer" aria-label="Permalink to “2.3 Software to Install on Your Local Computer”">​</a></h2><ol><li><p><strong>SSH Remote Login Tool</strong></p><ul><li>Windows: <a href="https://www.chiark.greenend.org.uk/~sgtatham/putty/latest.html" target="_blank" rel="noreferrer">PuTTY</a></li><li>macOS/Linux: Terminal</li></ul></li><li><p><strong>Remote File Copy Tool</strong></p><ul><li>Windows: <a href="https://winscp.net/eng/index.php" target="_blank" rel="noreferrer">WinSCP</a></li><li>macOS/Linux: Terminal</li></ul></li><li><p><strong>Reliable Text Editor</strong></p><ul><li>Windows/macOS/Linux: <a href="https://code.visualstudio.com" target="_blank" rel="noreferrer">VSCode</a></li></ul></li></ol><h2 id="_2-4-your-progress" tabindex="-1">2.4 Your Progress <a class="header-anchor" href="#_2-4-your-progress" aria-label="Permalink to “2.4 Your Progress”">​</a></h2><p>If you have prepared all the raw materials above, you have obtained the key to opening the door to a new world. So what are you waiting for? Let&#39;s move on to the next chapter and walk through that door!</p><blockquote><p>⬛⬛⬜⬜⬜⬜⬜⬜ 25%</p></blockquote>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};